def regex_search(pattern: str, text: str) -> bool:
    class Parser:
        def __init__(self, pattern: str):
            self.s = pattern
            self.n = len(pattern)
            self.i = 0

        def parse(self):
            node = self.parse_alt()
            if self.i != self.n:
                raise ValueError("invalid pattern")
            return node

        def parse_alt(self):
            branches = [self.parse_seq()]
            while self.i < self.n and self.s[self.i] == "|":
                self.i += 1
                branches.append(self.parse_seq())
            if len(branches) == 1:
                return branches[0]
            return ("alt", branches)

        def parse_seq(self):
            factors = []
            while self.i < self.n:
                c = self.s[self.i]
                if c in "|)":
                    break
                if c in "*+?":
                    raise ValueError("invalid quantifier")
                factors.append(self.parse_factor())

            if not factors:
                return ("empty",)
            if len(factors) == 1:
                return factors[0]
            return ("concat", factors)

        def parse_factor(self):
            c = self.s[self.i]

            if c == "^":
                self.i += 1
                return ("assert", 1)

            if c == "$":
                self.i += 1
                return ("assert", 2)

            if c == "\\":
                if self.i + 1 >= self.n:
                    raise ValueError("trailing backslash")
                ch = self.s[self.i + 1]
                self.i += 2
                return self.maybe_quantify(("lit", ch))

            if c == ".":
                self.i += 1
                return self.maybe_quantify(("dot",))

            if c == "[":
                cls = self.parse_class()
                return self.maybe_quantify(cls)

            if c == "(":
                group = self.parse_group()
                return self.maybe_quantify(group)

            self.i += 1
            return self.maybe_quantify(("lit", c))

        def maybe_quantify(self, atom):
            if self.i < self.n and self.s[self.i] in "*+?":
                op = self.s[self.i]
                self.i += 1
                return ("quant", op, atom)
            return atom

        def parse_group(self):
            self.i += 1
            node = self.parse_alt()
            if self.i >= self.n or self.s[self.i] != ")":
                raise ValueError("unmatched group")
            self.i += 1
            return node

        def parse_class(self):
            self.i += 1
            neg = False
            if self.i < self.n and self.s[self.i] == "^":
                neg = True
                self.i += 1

            ranges = []

            while True:
                if self.i >= self.n:
                    raise ValueError("unterminated character class")

                if self.s[self.i] == "]":
                    self.i += 1
                    break

                x = self.parse_class_char()

                if (
                    self.i < self.n
                    and self.s[self.i] == "-"
                    and self.i + 1 < self.n
                    and self.s[self.i + 1] != "]"
                ):
                    self.i += 1
                    y = self.parse_class_char()
                    sx, sy = ord(x), ord(y)
                    if sx > sy:
                        raise ValueError("invalid character range")
                    ranges.append((sx, sy))
                else:
                    ranges.append((ord(x), ord(x)))

            if not ranges:
                raise ValueError("empty character class")

            ranges.sort()
            merged = []
            for start, end in ranges:
                if not merged:
                    merged.append((start, end))
                else:
                    prev_start, prev_end = merged[-1]
                    if start <= prev_end + 1:
                        if end > prev_end:
                            merged[-1] = (prev_start, end)
                    else:
                        merged.append((start, end))

            return ("class", merged, neg)

        def parse_class_char(self):
            if self.i >= self.n:
                raise ValueError("unterminated character class")

            if self.s[self.i] == "\\":
                if self.i + 1 >= self.n:
                    raise ValueError("trailing backslash in class")
                ch = self.s[self.i + 1]
                self.i += 2
                return ch

            ch = self.s[self.i]
            self.i += 1
            return ch

    parser = Parser(pattern)
    ast = parser.parse()

    eps = []
    char_to = []
    char_kind = []
    char_lit = []
    char_ranges = []
    char_neg = []
    anchor = []

    def new_state():
        eps.append([])
        char_to.append(-1)
        char_kind.append(0)
        char_lit.append("")
        char_ranges.append(None)
        char_neg.append(False)
        anchor.append(0)
        return len(eps) - 1

    def add_eps(a, b):
        eps[a].append(b)

    def add_literal(s, d, ch):
        char_to[s] = d
        char_kind[s] = 1
        char_lit[s] = ch

    def add_dot(s, d):
        char_to[s] = d
        char_kind[s] = 2

    def add_class(s, d, ranges, neg):
        char_to[s] = d
        char_kind[s] = 3
        char_ranges[s] = ranges
        char_neg[s] = neg

    def add_anchor(s, kind):
        anchor[s] = kind

    def compile_node(node):
        tag = node[0]

        if tag == "empty":
            s = new_state()
            return s, s

        if tag == "lit":
            s = new_state()
            e = new_state()
            add_literal(s, e, node[1])
            return s, e

        if tag == "dot":
            s = new_state()
            e = new_state()
            add_dot(s, e)
            return s, e

        if tag == "class":
            s = new_state()
            e = new_state()
            add_class(s, e, node[1], node[2])
            return s, e

        if tag == "assert":
            s = new_state()
            e = new_state()
            add_anchor(s, node[1])
            add_eps(s, e)
            return s, e

        if tag == "concat":
            factors = node[1]
            start, end = compile_node(factors[0])
            for nxt in factors[1:]:
                ns, ne = compile_node(nxt)
                add_eps(end, ns)
                end = ne
            return start, end

        if tag == "alt":
            start = new_state()
            accept = new_state()
            for branch in node[1]:
                bs, be = compile_node(branch)
                add_eps(start, bs)
                add_eps(be, accept)
            return start, accept

        if tag == "quant":
            op = node[1]
            atom = node[2]
            s, e = compile_node(atom)

            if s == e:
                return s, e

            start = new_state()
            accept = new_state()

            if op == "*":
                add_eps(start, s)
                add_eps(start, accept)
                add_eps(e, start)
                add_eps(e, accept)
            elif op == "+":
                add_eps(start, s)
                add_eps(e, start)
                add_eps(e, accept)
            else:
                add_eps(start, s)
                add_eps(start, accept)
                add_eps(e, accept)

            return start, accept

        raise ValueError("invalid node")

    start_state, accept_state = compile_node(ast)
    text_len = len(text)

    def closure(states, pos):
        seen = set()
        stack = list(states)

        while stack:
            s = stack.pop()
            if s in seen:
                continue
            seen.add(s)

            a = anchor[s]
            if a == 0:
                stack.extend(eps[s])
            elif a == 1 and pos == 0:
                stack.extend(eps[s])
            elif a == 2 and pos == text_len:
                stack.extend(eps[s])

        return seen

    def matches_char(s, ch, cp):
        k = char_kind[s]
        if k == 0:
            return False
        if k == 1:
            return ch == char_lit[s]
        if k == 2:
            return True

        ranges = char_ranges[s]
        inside = False
        for lo, hi in ranges:
            if cp < lo:
                break
            if cp <= hi:
                inside = True
                break

        if char_neg[s]:
            return not inside
        return inside

    active = closure([start_state], 0)
    if accept_state in active:
        return True

    for pos, ch in enumerate(text):
        cp = ord(ch)
        next_states = [start_state]

        for s in active:
            if matches_char(s, ch, cp):
                next_states.append(char_to[s])

        active = closure(next_states, pos + 1)
        if accept_state in active:
            return True

    return False
